      "mainEntity": [
        {
          "@type": "Question",
          "name": "What's the most important layer in a facade system?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The substructure is arguably the most critical, since it transfers all structural loads back to the building and needs to accommodate thermal movement. A weak substructure will eventually cause problems regardless of how good the visible cladding is."
          }
        },
        {
          "@type": "Question",
          "name": "What is a rainscreen facade system?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A rainscreen system includes a ventilated air gap between the visible cladding and the waterproofing layer behind it, allowing any water that gets past the outer panel to drain and evaporate rather than penetrating the wall."
          }
        },
        {
          "@type": "Question",
          "name": "Does every facade system need insulation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Not necessarily, though it's increasingly specified on commercial buildings pursuing energy certifications and on premium residential projects given the cooling cost benefits it provides in India's climate."
          }
        },
        {
          "@type": "Question",
          "name": "Why does waterproofing matter if the cladding itself looks solid?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Many facade systems, especially perforated or ventilated ones, aren't fully weatherproof through the visible cladding alone, meaning the waterproofing layer behind it is doing the actual job of protecting the building from water intrusion."
          }
        },
        {
          "@type": "Question",
          "name": "How do I know if a facade company understands the full system, not just the panels?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ask them to explain their substructure design, waterproofing approach, and how thermal movement is accommodated, not just the panel material and finish. A company with genuine capability will discuss this in detail without hesitation."
          }
        }
      ]
